module axixclk #(
		parameter integer C_S_AXI_ID_WIDTH	= 2,
		parameter integer C_S_AXI_DATA_WIDTH	= 32,
		parameter integer C_S_AXI_ADDR_WIDTH	= 6,
		parameter [0:0]	OPT_WRITE_ONLY = 1'b0,
		parameter [0:0]	OPT_READ_ONLY = 1'b0,
		parameter	XCLOCK_FFS = 2,
		parameter	LGFIFO = 5
	) (
		input	wire				S_AXI_ACLK,
		input	wire				S_AXI_ARESETN,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_AWID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_AWADDR,
		input	wire [7 : 0]			S_AXI_AWLEN,
		input	wire [2 : 0]			S_AXI_AWSIZE,
		input	wire [1 : 0]			S_AXI_AWBURST,
		input	wire				S_AXI_AWLOCK,
		input	wire [3 : 0]			S_AXI_AWCACHE,
		input	wire [2 : 0]			S_AXI_AWPROT,
		input	wire [3 : 0]			S_AXI_AWQOS,
		input	wire				S_AXI_AWVALID,
		output	wire				S_AXI_AWREADY,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_WDATA,
		input	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] S_AXI_WSTRB,
		input	wire				S_AXI_WLAST,
		input	wire				S_AXI_WVALID,
		output	wire				S_AXI_WREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_BID,
		output	wire [1 : 0]			S_AXI_BRESP,
		output	wire				S_AXI_BVALID,
		input	wire				S_AXI_BREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_ARID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_ARADDR,
		input	wire [7 : 0]			S_AXI_ARLEN,
		input	wire [2 : 0]			S_AXI_ARSIZE,
		input	wire [1 : 0]			S_AXI_ARBURST,
		input	wire				S_AXI_ARLOCK,
		input	wire [3 : 0]			S_AXI_ARCACHE,
		input	wire [2 : 0]			S_AXI_ARPROT,
		input	wire [3 : 0]			S_AXI_ARQOS,
		input	wire				S_AXI_ARVALID,
		output	wire				S_AXI_ARREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_RID,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_RDATA,
		output	wire [1 : 0]			S_AXI_RRESP,
		output	wire				S_AXI_RLAST,
		output	wire				S_AXI_RVALID,
		input	wire				S_AXI_RREADY,
		input	wire				M_AXI_ACLK,
		output	wire				M_AXI_ARESETN,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_AWID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_AWADDR,
		output	wire [7 : 0]			M_AXI_AWLEN,
		output	wire [2 : 0]			M_AXI_AWSIZE,
		output	wire [1 : 0]			M_AXI_AWBURST,
		output	wire				M_AXI_AWLOCK,
		output	wire [3 : 0]			M_AXI_AWCACHE,
		output	wire [2 : 0]			M_AXI_AWPROT,
		output	wire [3 : 0]			M_AXI_AWQOS,
		output	wire				M_AXI_AWVALID,
		input	wire				M_AXI_AWREADY,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_WDATA,
		output	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] M_AXI_WSTRB,
		output	wire				M_AXI_WLAST,
		output	wire				M_AXI_WVALID,
		input	wire				M_AXI_WREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_BID,
		input	wire [1 : 0]			M_AXI_BRESP,
		input	wire				M_AXI_BVALID,
		output	wire				M_AXI_BREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_ARID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_ARADDR,
		output	wire [7 : 0]			M_AXI_ARLEN,
		output	wire [2 : 0]			M_AXI_ARSIZE,
		output	wire [1 : 0]			M_AXI_ARBURST,
		output	wire				M_AXI_ARLOCK,
		output	wire [3 : 0]			M_AXI_ARCACHE,
		output	wire [2 : 0]			M_AXI_ARPROT,
		output	wire [3 : 0]			M_AXI_ARQOS,
		output	wire				M_AXI_ARVALID,
		input	wire				M_AXI_ARREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_RID,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_RDATA,
		input	wire [1 : 0]			M_AXI_RRESP,
		input	wire				M_AXI_RLAST,
		input	wire				M_AXI_RVALID,
		output	wire				M_AXI_RREADY
	);

	// Local parameters
	localparam integer FIFO_DEPTH = 1 << LGFIFO;
	localparam integer FIFO_ADDR_WIDTH = LGFIFO;
	localparam integer FFS_STAGES = XCLOCK_FFS;

	// Internal signals
	wire [C_S_AXI_ID_WIDTH-1:0] s_awid;
	wire [C_S_AXI_ADDR_WIDTH-1:0] s_awaddr;
	wire [7:0] s_awlen;
	wire [2:0] s_awsize;
	wire [1:0] s_awburst;
	wire s_awlock;
	wire [3:0] s_awcache;
	wire [2:0] s_awprot;
	wire [3:0] s_awqos;
	wire s_awvalid;
	wire s_awready;

	wire [C_S_AXI_DATA_WIDTH-1:0] s_wdata;
	wire [(C_S_AXI_DATA_WIDTH/8)-1:0] s_wstrb;
	wire s_wlast;
	wire s_wvalid;
	wire s_wready;

	wire [C_S_AXI_ID_WIDTH-1:0] s_bid;
	wire [1:0] s_bresp;
	wire s_bvalid;
	wire s_bready;

	wire [C_S_AXI_ID_WIDTH-1:0] s_arid;
	wire [C_S_AXI_ADDR_WIDTH-1:0] s_araddr;
	wire [7:0] s_arlen;
	wire [2:0] s_arsize;
	wire [1:0] s_arburst;
	wire s_arlock;
	wire [3:0] s_arcache;
	wire [2:0] s_arprot;
	wire [3:0] s_arqos;
	wire s_arvalid;
	wire s_arready;

	wire [C_S_AXI_ID_WIDTH-1:0] s_rid;
	wire [C_S_AXI_DATA_WIDTH-1:0] s_rdata;
	wire [1:0] s_rresp;
	wire s_rlast;
	wire s_rvalid;
	wire s_rready;

	wire m_awid;
	wire [C_S_AXI_ADDR_WIDTH-1:0] m_awaddr;
	wire [7:0] m_awlen;
	wire [2:0] m_awsize;
	wire [1:0] m_awburst;
	wire m_awlock;
	wire [3:0] m_awcache;
	wire [2:0] m_awprot;
	wire [3:0] m_awqos;
	wire m_awvalid;
	wire m_awready;

	wire [C_S_AXI_DATA_WIDTH-1:0] m_wdata;
	wire [(C_S_AXI_DATA_WIDTH/8)-1:0] m_wstrb;
	wire m_wlast;
	wire m_wvalid;
	wire m_wready;

	wire [C_S_AXI_ID_WIDTH-1:0] m_bid;
	wire [1:0] m_bresp;
	wire m_bvalid;
	wire m_bready;

	wire [C_S_AXI_ID_WIDTH-1:0] m_arid;
	wire [C_S_AXI_ADDR_WIDTH-1:0] m_araddr;
	wire [7:0] m_arlen;
	wire [2:0] m_arsize;
	wire [1:0] m_arburst;
	wire m_arlock;
	wire [3:0] m_arcache;
	wire [2:0] m_arprot;
	wire [3:0] m_arqos;
	wire m_arvalid;
	wire m_arready;

	wire [C_S_AXI_ID_WIDTH-1:0] m_rid;
	wire [C_S_AXI_DATA_WIDTH-1:0] m_rdata;
	wire [1:0] m_rresp;
	wire m_rlast;
	wire m_rvalid;
	wire m_rready;

	// Reset synchronization
	reg [FFS_STAGES-1:0] m_reset_sync;
	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			m_reset_sync <= {FFS_STAGES{1'b0}};
		else
			m_reset_sync <= {m_reset_sync[FFS_STAGES-2:0], 1'b1};
	end
	assign M_AXI_ARESETN = m_reset_sync[FFS_STAGES-1];

	// AW channel: S to M
	// FIFO for AW channel
	reg [C_S_AXI_ID_WIDTH-1:0] aw_fifo_data [0:FIFO_DEPTH-1];
	reg [C_S_AXI_ADDR_WIDTH-1:0] aw_fifo_addr [0:FIFO_DEPTH-1];
	reg [7:0] aw_fifo_len [0:FIFO_DEPTH-1];
	reg [2:0] aw_fifo_size [0:FIFO_DEPTH-1];
	reg [1:0] aw_fifo_burst [0:FIFO_DEPTH-1];
	reg aw_fifo_lock [0:FIFO_DEPTH-1];
	reg [3:0] aw_fifo_cache [0:FIFO_DEPTH-1];
	reg [2:0] aw_fifo_prot [0:FIFO_DEPTH-1];
	reg [3:0] aw_fifo_qos [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] aw_fifo_wr_ptr;
	reg [FIFO_ADDR_WIDTH:0] aw_fifo_rd_ptr;
	reg aw_fifo_full;
	reg aw_fifo_empty;

	// AW write in S clock domain
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			aw_fifo_wr_ptr <= 0;
			aw_fifo_full <= 1'b0;
		end else begin
			if (s_awvalid && s_awready && !aw_fifo_full) begin
				aw_fifo_data[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWID;
				aw_fifo_addr[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWADDR;
				aw_fifo_len[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWLEN;
				aw_fifo_size[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWSIZE;
				aw_fifo_burst[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWBURST;
				aw_fifo_lock[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWLOCK;
				aw_fifo_cache[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWCACHE;
				aw_fifo_prot[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWPROT;
				aw_fifo_qos[aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWQOS;
				aw_fifo_wr_ptr <= aw_fifo_wr_ptr + 1;
			end
		end
	end

	// AW read in M clock domain
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			aw_fifo_rd_ptr <= 0;
			aw_fifo_empty <= 1'b1;
		end else begin
			if (m_awvalid && m_awready && !aw_fifo_empty) begin
				aw_fifo_rd_ptr <= aw_fifo_rd_ptr + 1;
			end
		end
	end

	// AW FIFO status
	always @(*) begin
		if (aw_fifo_wr_ptr[FIFO_ADDR_WIDTH] != aw_fifo_rd_ptr[FIFO_ADDR_WIDTH]) begin
			aw_fifo_full = (aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0] == aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
			aw_fifo_empty = 1'b0;
		end else begin
			aw_fifo_full = 1'b0;
			aw_fifo_empty = (aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0] == aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
		end
	end

	// AW output in M clock domain
	always @(*) begin
		if (aw_fifo_empty) begin
			m_awid = {C_S_AXI_ID_WIDTH{1'b0}};
			m_awaddr = {C_S_AXI_ADDR_WIDTH{1'b0}};
			m_awlen = 8'b0;
			m_awsize = 3'b0;
			m_awburst = 2'b0;
			m_awlock = 1'b0;
			m_awcache = 4'b0;
			m_awprot = 3'b0;
			m_awqos = 4'b0;
			m_awvalid = 1'b0;
		end else begin
			m_awid = aw_fifo_data[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awaddr = aw_fifo_addr[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awlen = aw_fifo_len[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awsize = aw_fifo_size[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awburst = aw_fifo_burst[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awlock = aw_fifo_lock[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awcache = aw_fifo_cache[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awprot = aw_fifo_prot[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awqos = aw_fifo_qos[aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			m_awvalid = 1'b1;
		end
	end

	// AW ready in S clock domain
	assign s_awready = !aw_fifo_full;
	assign S_AXI_AWREADY = s_awready;

	// W channel: S to M
	// FIFO for W channel
	reg [C_S_AXI_DATA_WIDTH-1:0] w_fifo_data [0:FIFO_DEPTH-1];
	reg [(C_S_AXI_DATA_WIDTH/8)-1:0] w_fifo_strb [0:FIFO_DEPTH-1];
	reg w_fifo_last [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] w_fifo_wr_ptr;
	reg [FIFO_ADDR_WIDTH:0] w_fifo_rd_ptr;
	reg w_fifo_full;
	reg w_fifo_empty;

	// W write in S clock domain
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			w_fifo_wr_ptr <= 0;
			w_fifo_full <= 1'b0;
		end else begin
			if (s_wvalid && s_wready && !w_fifo_full) begin
				w_fifo_data[w_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_WDATA;
				w_fifo_strb[w_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_WSTRB;
				w_fifo_last[w_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_WLAST;
				w_fifo_wr_ptr <= w_fifo_wr_ptr + 1;
			end
		end
	end

	// W read in M clock domain
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			w_fifo_rd_ptr <= 0;
			w_fifo_empty <= 1'b1;
		end else begin
			if (m_wvalid && m_wready && !w_fifo_empty) begin
				w_fifo_rd_ptr <= w_fifo_rd_ptr + 1;
			end
		end
	end

	// W FIFO status
	always @(*) begin
		if (w_fifo_wr_ptr[FIFO_ADDR_WIDTH] != w_fifo_rd_ptr[FIFO_ADDR_WIDTH]) begin
			w_fifo_full = (w_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0] == w_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
			w_fifo_empty = 1'b0;
		end else begin
			w_fifo_full = 1'b0;
			w_fifo_empty = (w_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0] == w_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
		end
	end

	// W output in M clock domain - hold one extra M_AXI clock before M_AXI_WVALID
	reg [C_S_AXI_DATA_WIDTH-1:0] w_out_data;
	reg [(C_S_AXI_DATA_WIDTH/8)-1:0] w_out_strb;
	reg w_out_last;
	reg w_out_valid;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			w_out_data <= {C_S_AXI_DATA_WIDTH{1'b0}};
			w_out_strb <= {(C_S_AXI_DATA_WIDTH/8){1'b0}};
			w_out_last <= 1'b0;
			w_out_valid <= 1'b0;
		end else begin
			if (!w_fifo_empty) begin
				w_out_data <= w_fifo_data[w_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				w_out_strb <= w_fifo_strb[w_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				w_out_last <= w_fifo_last[w_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				w_out_valid <= 1'b1;
			end else begin
				w_out_valid <= 1'b0;
			end
		end
	end

	assign m_wdata = w_out_data;
	assign m_wstrb = w_out_strb;
	assign m_wlast = w_out_last;
	assign m_wvalid = w_out_valid;

	// W ready in S clock domain
	assign s_wready = !w_fifo_full;
	assign S_AXI_WREADY = s_wready;

	// B channel: M to S
	// FIFO for B channel
	reg [C_S_AXI_ID_WIDTH-1:0] b_fifo_id [0:FIFO_DEPTH-1];
	reg [1:0] b_fifo_resp [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] b_fifo_wr_ptr;
	reg [FIFO_ADDR_WIDTH:0] b_fifo_rd_ptr;
	reg b_fifo_full;
	reg b_fifo_empty;

	// B write in M clock domain
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			b_fifo_wr_ptr <= 0;
			b_fifo_full <= 1'b0;
		end else begin
			if (M_AXI_BVALID && M_AXI_BREADY && !b_fifo_full) begin
				b_fifo_id[b_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= M_AXI_BID;
				b_fifo_resp[b_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= M_AXI_BRESP;
				b_fifo_wr_ptr <= b_fifo_wr_ptr + 1;
			end
		end
	end

	// B read in S clock domain
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			b_fifo_rd_ptr <= 0;
			b_fifo_empty <= 1'b1;
		end else begin
			if (s_bvalid && s_bready && !b_fifo_empty) begin
				b_fifo_rd_ptr <= b_fifo_rd_ptr + 1;
			end
		end
	end

	// B FIFO status
	always @(*) begin
		if (b_fifo_wr_ptr[FIFO_ADDR_WIDTH] != b_fifo_rd_ptr[FIFO_ADDR_WIDTH]) begin
			b_fifo_full = (b_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0] == b_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
			b_fifo_empty = 1'b0;
		end else begin
			b_fifo_full = 1'b0;
			b_fifo_empty = (b_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0] == b_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
		end
	end

	// B output in S clock domain
	always @(*) begin
		if (b_fifo_empty) begin
			s_bid = {C_S_AXI_ID_WIDTH{1'b0}};
			s_bresp = 2'b0;
			s_bvalid = 1'b0;
		end else begin
			s_bid = b_fifo_id[b_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			s_bresp = b_fifo_resp[b_fifo_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
			s_bvalid = 1'b1;
		end
	end

	// B ready in M clock domain
	assign m_bready = !b_fifo_full;
	assign M_AXI_BREADY = m_bready;

	// B output to S
	assign S_AXI_BID = s_bid;
	assign S_AXI_BRESP = s_bresp;
	assign S_AXI_BVALID = s_bvalid;

	// AR channel: S to M
	// FIFO for AR channel
	reg [C_S_AXI_ID_WIDTH-1:0] ar_fifo_id [0:FIFO_DEPTH-1];
	reg [C_S_AXI_ADDR_WIDTH-1:0] ar_fifo_addr [0:FIFO_DEPTH-1];
	reg [7:0] ar_fifo_len [0:FIFO_DEPTH-1];
	reg [2:0] ar_fifo_size [0:FIFO_DEPTH-1];
	reg [1:0] ar_fifo_burst [0:FIFO_DEPTH-1];
	reg ar_fifo_lock [0:FIFO_DEPTH-1];
	reg [3:0] ar_fifo_cache [0:FIFO_DEPTH-1];
	reg [2:0] ar_fifo_prot [0:FIFO_DEPTH-1];
	reg [3:0] ar_fifo_qos [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] ar_fifo_wr_ptr;
	reg [FIFO_ADDR_WIDTH:0] ar_fifo_rd_ptr;
	reg ar_fifo_full;
	reg ar_fifo_empty;

	// AR write in S clock domain
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			ar_fifo_wr_ptr <= 0;
			ar_fifo_full <= 1'b0;
		end else begin
			if (s_arvalid && s_arready && !ar_fifo_full) begin
				ar_fifo_id[ar_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARID;
				ar_fifo_addr[ar_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARADDR;
				ar_fifo_len[ar_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARLEN;
				ar_fifo_size[ar_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARSIZE;
				ar_fifo_burst[ar_fifo_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARBURST;
